begin;
create schema if not exists udam_private;
revoke all on schema udam_private from public,anon;
grant usage on schema udam_private to authenticated,service_role;
create table if not exists udam_private.family_records_backup_v20 as table public.family_records;
create table if not exists udam_private.approvals_backup_v20 as table public.user_approvals;
revoke all on all tables in schema udam_private from public,anon,authenticated;
create table if not exists udam_private.admins(user_id uuid primary key references auth.users(id) on delete cascade);
insert into udam_private.admins select id from auth.users where lower(email)='tankbttl@gmail.com' and email_confirmed_at is not null on conflict do nothing;
create or replace function udam_private.is_admin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from udam_private.admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid() and u.email_confirmed_at is not null)$$;
create or replace function udam_private.is_approved() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.user_approvals a join auth.users u on u.id=a.user_id where a.user_id=auth.uid() and a.is_approved and u.email_confirmed_at is not null)$$;
create or replace function public.udam_is_admin() returns boolean language sql stable security invoker set search_path='' as $$select udam_private.is_admin()$$;
create or replace function public.udam_is_approved() returns boolean language sql stable security invoker set search_path='' as $$select udam_private.is_approved()$$;
revoke all on function udam_private.is_admin(),udam_private.is_approved(),public.udam_is_admin(),public.udam_is_approved() from public,anon;
grant execute on function udam_private.is_admin(),udam_private.is_approved(),public.udam_is_admin(),public.udam_is_approved() to authenticated;
create or replace function udam_private.create_pending_approval() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.user_approvals(user_id,email,is_approved) values(new.id,lower(new.email),false) on conflict(user_id) do nothing; return new; end$$;
revoke all on function udam_private.create_pending_approval(),public.udam_create_pending_approval() from public,anon,authenticated;
drop trigger if exists udam_auth_user_approval on auth.users;
create trigger udam_auth_user_approval after insert on auth.users for each row execute function udam_private.create_pending_approval();
revoke all on public.user_approvals,public.family_records from anon;
-- Keep existing owner/admin RLS policies; their helper functions now require verified server-side identity.
create table public.lineage_profiles(user_id uuid primary key references auth.users(id) on delete cascade,clan_name text not null check(length(clan_name) between 1 and 80),display_name text check(length(display_name)<=80),is_discoverable boolean not null default false,allow_contact_requests boolean not null default false,updated_at timestamptz not null default now());
create table public.lineage_requests(id uuid primary key default gen_random_uuid(),requester_user_id uuid not null references auth.users(id) on delete cascade,target_user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','rejected','revoked')),created_at timestamptz not null default now(),responded_at timestamptz,check(requester_user_id<>target_user_id),unique(requester_user_id,target_user_id));
create unique index lineage_request_pair on public.lineage_requests(least(requester_user_id,target_user_id),greatest(requester_user_id,target_user_id));
create index lineage_requests_target on public.lineage_requests(target_user_id,status);
alter table public.lineage_profiles enable row level security;
alter table public.lineage_requests enable row level security;
revoke all on public.lineage_profiles,public.lineage_requests from public,anon;
grant select,insert,update,delete on public.lineage_profiles to authenticated;
grant select,insert,update on public.lineage_requests to authenticated;
create table udam_private.contact_tickets(owner_id uuid not null,target_id uuid not null,expires_at timestamptz not null,primary key(owner_id,target_id));
create table udam_private.budgets(user_id uuid not null,kind text not null,bucket timestamptz not null,total integer not null,primary key(user_id,kind,bucket));
revoke all on udam_private.admins,udam_private.contact_tickets,udam_private.budgets from public,anon,authenticated;
create function udam_private.connected(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and auth.uid() in (a,b) and exists(select 1 from public.lineage_requests r where r.status='accepted' and ((r.requester_user_id=a and r.target_user_id=b) or (r.requester_user_id=b and r.target_user_id=a)))$$;
create function udam_private.can_view_profile(target uuid) returns boolean language sql stable security definer set search_path='' as $$select udam_private.is_approved() and exists(select 1 from public.user_approvals a join auth.users u on u.id=a.user_id where a.user_id=target and a.is_approved and u.email_confirmed_at is not null) and (auth.uid()=target or udam_private.connected(auth.uid(),target) or exists(select 1 from public.lineage_requests r where (r.requester_user_id=auth.uid() and r.target_user_id=target) or (r.target_user_id=auth.uid() and r.requester_user_id=target)) or exists(select 1 from public.lineage_profiles t join public.lineage_profiles me on me.user_id=auth.uid() where t.user_id=target and t.is_discoverable and lower(trim(me.clan_name))=lower(trim(t.clan_name))))$$;
create function udam_private.can_request(target uuid) returns boolean language sql stable security definer set search_path='' as $$select udam_private.is_approved() and target<>auth.uid() and exists(select 1 from public.user_approvals a join auth.users u on u.id=a.user_id where a.user_id=target and a.is_approved and u.email_confirmed_at is not null) and (exists(select 1 from public.lineage_profiles t join public.lineage_profiles me on me.user_id=auth.uid() where t.user_id=target and t.is_discoverable and lower(trim(me.clan_name))=lower(trim(t.clan_name))) or exists(select 1 from udam_private.contact_tickets t where t.owner_id=auth.uid() and t.target_id=target and t.expires_at>now()))$$;
revoke all on function udam_private.connected(uuid,uuid),udam_private.can_view_profile(uuid),udam_private.can_request(uuid) from public,anon;
grant execute on function udam_private.connected(uuid,uuid),udam_private.can_view_profile(uuid),udam_private.can_request(uuid) to authenticated;
create policy profile_read on public.lineage_profiles for select to authenticated using(user_id=auth.uid() or udam_private.can_view_profile(user_id));
create policy profile_insert on public.lineage_profiles for insert to authenticated with check(user_id=auth.uid() and udam_private.is_approved());
create policy profile_update on public.lineage_profiles for update to authenticated using(user_id=auth.uid() and udam_private.is_approved()) with check(user_id=auth.uid() and udam_private.is_approved());
create policy profile_delete on public.lineage_profiles for delete to authenticated using(user_id=auth.uid());
create policy request_read on public.lineage_requests for select to authenticated using(udam_private.is_approved() and auth.uid() in (requester_user_id,target_user_id));
create policy request_insert on public.lineage_requests for insert to authenticated with check(requester_user_id=auth.uid() and status='pending' and udam_private.can_request(target_user_id));
create policy request_update on public.lineage_requests for update to authenticated using(udam_private.is_approved() and auth.uid() in (requester_user_id,target_user_id)) with check(udam_private.is_approved() and auth.uid() in (requester_user_id,target_user_id));
create function udam_private.guard_request() returns trigger language plpgsql security invoker set search_path='' as $$begin if new.id<>old.id or new.requester_user_id<>old.requester_user_id or new.target_user_id<>old.target_user_id or new.created_at<>old.created_at then raise exception 'Request participants are immutable';end if;if not ((old.status='pending' and new.status in ('accepted','rejected') and auth.uid()=old.target_user_id) or (old.status in ('pending','accepted') and new.status='revoked' and auth.uid() in(old.requester_user_id,old.target_user_id))) then raise exception 'Invalid request transition';end if;new.responded_at=now();return new;end$$;
revoke all on function udam_private.guard_request() from public,anon;
create trigger guard_lineage_request before update on public.lineage_requests for each row execute function udam_private.guard_request();
create function udam_private.find_contact(contact text) returns table(user_id uuid,display_name text) language plpgsql security definer set search_path='' as $$declare hits integer;begin if not udam_private.is_approved() then raise exception 'Approval required';end if;if length(contact)>254 or not (position('@' in contact)>1 or contact ~ '^\+[1-9][0-9]{7,14}$') then return;end if;insert into udam_private.budgets values(auth.uid(),'contacts',date_trunc('day',now()),1) on conflict(user_id,kind,bucket) do update set total=udam_private.budgets.total+1 returning total into hits;if hits>20 then raise exception 'Daily lookup limit reached';end if;return query with candidate as(select p.user_id,p.display_name from public.lineage_profiles p join auth.users u on u.id=p.user_id join public.user_approvals a on a.user_id=p.user_id where p.allow_contact_requests and a.is_approved and p.user_id<>auth.uid() and u.email_confirmed_at is not null and ((lower(u.email)=lower(trim(contact))) or (u.phone_confirmed_at is not null and regexp_replace(u.phone,'[^0-9]','','g')=regexp_replace(contact,'[^0-9]','','g'))) limit 1),ticket as(insert into udam_private.contact_tickets select auth.uid(),c.user_id,now()+interval '10 minutes' from candidate c on conflict(owner_id,target_id) do update set expires_at=excluded.expires_at returning target_id) select c.user_id,c.display_name from candidate c join ticket t on t.target_id=c.user_id;end$$;
create function public.find_lineage_contact(contact text) returns table(user_id uuid,display_name text) language sql security invoker set search_path='' as $$select * from udam_private.find_contact(contact)$$;
revoke all on function udam_private.find_contact(text),public.find_lineage_contact(text) from public,anon;
grant execute on function udam_private.find_contact(text),public.find_lineage_contact(text) to authenticated;
create function udam_private.connected_lineage(peer_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin if not udam_private.is_approved() or not udam_private.connected(auth.uid(),peer_id) or not exists(select 1 from public.user_approvals a join auth.users u on u.id=a.user_id where a.user_id=peer_id and a.is_approved and u.email_confirmed_at is not null) then raise exception 'No accepted connection';end if;with recursive nodes as(select n from public.family_records f cross join lateral jsonb_array_elements(f.people) n where f.user_id=peer_id),ancestors as(select n,0 depth,array[n->>'id'] path from nodes where n->>'relation'='Би' union all select p.n,a.depth+1,a.path||(p.n->>'id') from ancestors a cross join lateral jsonb_array_elements_text(coalesce(a.n->'parentIds','[]')) pid join nodes p on p.n->>'id'=pid where a.depth<5 and not(p.n->>'id'=any(a.path))),minimal as(select distinct jsonb_build_object('id',n->>'id','name',n->>'name','clanName',n->>'clanName','fatherName',n->>'fatherName','givenName',n->>'givenName','birthYear',n->>'birthYear','relation',n->>'relation','parentIds',coalesce(n->'parentIds','[]')) n from ancestors) select jsonb_build_object('people',coalesce(jsonb_agg(n),'[]')) into result from minimal;return result;end$$;
create function public.get_connected_lineage(peer_id uuid) returns jsonb language sql security invoker set search_path='' as $$select udam_private.connected_lineage(peer_id)$$;
revoke all on function udam_private.connected_lineage(uuid),public.get_connected_lineage(uuid) from public,anon;
grant execute on function udam_private.connected_lineage(uuid),public.get_connected_lineage(uuid) to authenticated;
create function public.consume_lineage_ai_budget(subject_id uuid) returns boolean language plpgsql security invoker set search_path='' as $$declare hits integer;begin insert into udam_private.budgets values(subject_id,'ai',date_trunc('hour',now()),1) on conflict(user_id,kind,bucket) do update set total=udam_private.budgets.total+1 returning total into hits;return hits<=10;end$$;
revoke all on function public.consume_lineage_ai_budget(uuid) from public,anon,authenticated;
grant select,insert,update on udam_private.budgets to service_role;
grant execute on function public.consume_lineage_ai_budget(uuid) to service_role;
notify pgrst,'reload schema';
commit;
